  // Sports function to call.
  fn: "schedule" | "standings";
  // League to look up.
  league: "nba" | "wnba" | "nfl" | "nhl" | "mlb" | "epl" | "ncaamb" | "ncaawb" | "ipl";
  // Locale for the lookup.
  locale?: string;
  // Number of games to return.
  num_games?: number;
  // Opponent to use with `team` when narrowing the lookup.
